#!/usr/bin/env bash
# Creates .env with strong random secrets (Linux/macOS). Refuses to overwrite an existing .env.
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
env_file="$root/.env"

if [ -e "$env_file" ]; then
  echo ".env already exists - not overwriting. Delete it first if you really want new secrets." >&2
  exit 1
fi

secret() { openssl rand -base64 "$1" | tr '+/' '-_' | tr -d '=\n'; }
admin_password="$(secret 18)A9"   # suffix guarantees at least one letter and one digit

umask 077
cat > "$env_file" <<ENVEOF
# Generated by scripts/generate-env.sh - NEVER commit this file.
JWT_SECRET=$(secret 48)
INTERNAL_API_KEY=$(secret 48)
REDIS_PASSWORD=$(secret 32)
AUTH_DB_PASSWORD=$(secret 32)
PRODUCT_DB_PASSWORD=$(secret 32)
AUTH_DB_NAME=authdb
AUTH_DB_USER=auth_user
PRODUCT_DB_NAME=productdb
PRODUCT_DB_USER=product_user
JWT_ISSUER=api-gateway-auth
JWT_AUDIENCE=api-gateway
JWT_EXPIRATION_MINUTES=15
REQUIRE_HTTPS=false
TRUSTED_PROXY_HOPS=0
CORS_ALLOWED_ORIGINS=
BOOTSTRAP_ADMIN_USERNAME=admin
BOOTSTRAP_ADMIN_PASSWORD=$admin_password
DOMAIN=localhost
ENVEOF

echo "Created $env_file"
echo "First admin login -> username: admin   password: $admin_password"
echo "Save that password in a password manager, then delete the two BOOTSTRAP_ADMIN_* lines from .env after the first start."
